var Q36=[
{n:1,q:"La tasa de alcoholemia se obtiene con respecto a unos determinados valores analizados:",o:{a:"En sangre.",b:"En aire espirado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"La tasa de alcoholemia se determina analizando dos medios: la sangre (a) y el aire espirado (b), siendo ambas formas válidas para obtenerla."}},
{n:2,q:"Los efectos que produce el alcohol varían:",o:{a:"Dependiendo de la persona.",b:"Dependiendo de la cantidad de alcohol ingerida.",c:"Dependiendo de las circunstancias en que se produce el consumo.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Los efectos del alcohol varían según la persona (a), la cantidad ingerida (b) y las circunstancias del consumo (c); los tres factores son determinantes."}},
{n:3,q:"Indique la afirmación incorrecta:",o:{a:"La defensa metabólica contra el alcohol es muy baja en edades inferiores a 17 años, por lo que la ingestión en estos individuos produce más alteraciones orgánicas y psicológicas.",b:"Se ha demostrado que la mujer está mejor dotada que el hombre para la defensa enzimática contra el alcohol.",c:"Con la misma cantidad de alcohol ingerida, la alcoholemia es menor en las personas gruesas que en las delgadas.",d:"En determinadas condiciones como fatiga, embarazo o ingerir alcohol con el estómago vacío, el alcohol se absorbe más rápidamente y produce efectos más rápidos en el sujeto."},correct:"b",why:{b:"La opción b) es incorrecta: está demostrado que la mujer está PEOR dotada (no mejor) que el hombre para la defensa enzimática contra el alcohol, lo que genera mayor vulnerabilidad."}},
{n:4,q:"Según los estudios realizados por Widmark respecto al efecto y consecuencias del consumo de alcohol, entre 0,25 y 0,40 mg de alcohol/litro de aire espirado:",o:{a:"La persona está eufórica y locuaz y los reflejos y la coordinación mano-ojo disminuyen.",b:"El estado de ánimo de la persona está exaltado y se siente fuerte y segura de si misma.",c:"Posible cansancio o fatiga que no desaparece; pero sí que desaparece el conocimiento que el sujeto tiene de ellos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Entre 0,25 y 0,40 mg/l de aire espirado, Widmark describe euforia y disminución de reflejos (a), estado de ánimo exaltado (b) y fatiga sin percepción de la misma (c); todos son efectos correctos."}},
{n:5,q:"Según los estudios realizados por Widmark respecto al efecto y consecuencias del consumo de alcohol, entre 0,40 y 0,75 mg de alcohol/litro de aire espirado:",o:{a:"Los reflejos están más alterados y los movimientos son más torpes.",b:"La excitación conlleva un comportamiento más peligroso y la locuacidad se vuelve incoherencia verbal.",c:"La persona canta, grita, discute o pelea, tomando iniciativas impulsivamente.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Entre 0,40 y 0,75 mg/l, Widmark describe mayor torpeza y alteración de reflejos (a), comportamiento más peligroso e incoherencia verbal (b) e impulsividad con conductas agresivas (c); todos son efectos correctos."}},
{n:6,q:"Según los estudios realizados por Widmark respecto al efecto y consecuencias del consumo de alcohol, entre 0,75 y 2 mg. de alcohol/litro de aire espirado...",o:{a:"Se produce afectación sensible al sistema de equilibrio y la persona anda titubeante con pérdida de estabilidad.",b:"Se nubla la vista apareciendo dioplías.",c:"Disminuye la sensibilidad y la conducta se vuelve psicótica. Sueño comatoso con riesgo de muerte.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Entre 0,75 y 2 mg/l se producen los tres efectos: pérdida de equilibrio (a), visión doble o dioplías (b) y conducta psicótica con riesgo de coma (c)."}},
{n:7,q:"Respecto a la normativa aplicable en materia de alcoholemia, en el ámbito administrativo se determinan:",o:{a:"Los requisitos reglamentarios para la realización de las pruebas y los derechos y obligaciones de los conductores con respecto a las mismas.",b:"Las tasas máximas permitidas.",c:"Las sanciones administrativas previstas para cada caso.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"La normativa administrativa en materia de alcoholemia establece los requisitos de las pruebas (a), las tasas máximas (b) y las sanciones previstas (c); los tres aspectos son correctos."}},
{n:8,q:"En lo que respecta a la conducción de vehículos, la normativa administrativa en materia de bebidas alcohólicas, estupefacientes, psicotrópicos, estimulantes u otras sustancias análogas se contiene en:",o:{a:"El artículo 14 del RDL 6/2015, por el que se aprueba el texto refundido de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.",b:"El Capítulo VI del Título I del Real Decreto 1428/2003 de 21 de noviembre por el que se aprueba el Reglamento General de Circulación.",c:"Los artículos 14 a 26 del Real Decreto 1428/2003 de 21 de noviembre por el que se aprueba el Reglamento General de Circulación.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"La normativa administrativa sobre alcohol y drogas en la conducción se contiene principalmente en el artículo 14 del RDL 6/2015 (Ley de Seguridad Vial)."}},
{n:9,q:"Los tipos penales relacionados con la conducción de vehículos bajo los efectos de bebidas alcohólicas, estupefacientes, psicotrópicos, estimulantes u otras sustancias análogas se encuentran regulados en...",o:{a:"El artículo 279.1 del Código Penal.",b:"El artículo 279.2 del Código Penal.",c:"El artículo 379.1 del Código Penal.",d:"El artículo 379.2 del Código Penal."},correct:"d",why:{d:"Los tipos penales de conducción bajo efectos de alcohol o drogas se regulan en el artículo 379.2 del Código Penal."}},
{n:10,q:"Los tipos penales relacionados con la negativa a someterse a las pruebas para la comprobación de las tasas de alcoholemia y la presencia de drogas tóxicas, estupefacientes, psicotrópicos, estimulantes u otras sustancias análogas en el organismo de los conductores, se encuentran regulados en...",o:{a:"El artículo 379.1 del Código Penal.",b:"El artículo 380 del Código Penal.",c:"El artículo 383 del Código Penal.",d:"El artículo 379.2 del Código Penal."},correct:"c",why:{c:"La negativa a someterse a las pruebas de alcoholemia o drogas está tipificada como delito en el artículo 383 del Código Penal."}},
{n:11,q:"Según el artículo 14 de la Ley de Seguridad Vial, no podrá circular por las vías objeto de esta ley, el conductor de cualquier vehículo con tasas de alcohol:",o:{a:"Superiores a las que reglamentariamente se determinen.",b:"Superiores a 0'15 gramos de alcohol por litro de aire espirado.",c:"Superiores a 0'25 mg de alcohol por litro de sangre.",d:"Superiores a 0'60 mg de alcohol por litro de aire espirado."},correct:"a",why:{a:"El artículo 14 de la LSV establece la prohibición de circular con tasas de alcohol superiores a las que reglamentariamente se determinen, remitiendo al desarrollo reglamentario para las cifras concretas."}},
{n:12,q:"Según el artículo 14 de la Ley de Seguridad Vial, en ningún caso el conductor menor de edad podrá circular por las vías con unas tasas de alcohol en sangre...",o:{a:"Superiores a las que reglamentariamente se determinen.",b:"Superiores a 0'15 gramos de alcohol por litro de aire espirado.",c:"Superiores a 0'25 mg de alcohol por litro de sangre.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{d:"Ninguna de las opciones refleja exactamente lo dispuesto en el art.14 LSV para menores; la ley establece una remisión reglamentaria y la prohibición específica está en el RGC."}},
{n:13,q:"Indique la respuesta incorrecta:",o:{a:"Todos los conductores de vehículos quedan obligados a someterse a las pruebas que se establezcan para la detección de posibles intoxicaciones por alcohol.",b:"Todos los usuarios de la vía están obligados a someterse a las pruebas que se establezcan para la detección de posibles intoxicaciones por alcohol.",c:"Las pruebas para la detección de la posible intoxicación por alcohol consistirán normalmente en la verificación del aire espirado mediante etilómetros oficialmente autorizados.",d:"Las pruebas para la detección de la posible intoxicación por alcohol se practicarán por los agentes encargados de la vigilancia del tráfico."},correct:"b",why:{b:"La opción b) es incorrecta: no todos los usuarios de la vía están obligados sin más; la obligación de los demás usuarios (no conductores) está condicionada a determinadas circunstancias como haber cometido una infracción o estar implicados en accidente."}},
{n:14,q:"De conformidad con lo establecido en el artículo 14 de la Ley de Seguridad Vial, todos los conductores de vehículos quedan obligados a someterse a las pruebas de detección de alcohol que se establezcan, y los demás usuarios de la vía estarán obligados:",o:{a:"Cuando hayan cometido una infracción conforme a lo tipificado en esta ley.",b:"Cuando sean requeridos al efecto por la autoridad o sus agentes, dentro de los programas de controles preventivos ordenados por dicha autoridad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Los demás usuarios de la vía (no conductores) están obligados cuando hayan cometido una infracción conforme a lo tipificado en la LSV."}},
{n:15,q:"De conformidad con lo establecido en el artículo 14 de la Ley de Seguridad Vial, todos los conductores de vehículos quedan obligados a someterse a las pruebas de detección de alcohol que se establezcan, y los demás usuarios de la vía estarán obligados:",o:{a:"Cuando presenten síntomas evidentes, manifestaciones que denoten o hechos que permitan razonablemente presumir que se hallan bajo la influencia de bebidas alcohólicas.",b:"Cuando se hallen implicados en algún accidente de circulación.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Los demás usuarios de la vía están también obligados cuando se hallen implicados en algún accidente de circulación."}},
{n:16,q:"Los agentes de la autoridad, encargados de la vigilancia del tráfico, podrán someter a las pruebas de detección del grado de intoxicación alcohólica a:",o:{a:"Quienes conduzcan cualquier vehículo con síntomas evidentes, manifestaciones que denoten, o hechos que permitan razonablemente presumir que lo hacen bajo la influencia de bebidas alcohólicas.",b:"Cualquier usuario de la vía, implicado directa o indirectamente como posible responsable en un accidente de circulación.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Los agentes pueden someter a pruebas tanto a quienes presenten síntomas de conducción bajo influencia alcohólica (a) como a cualquier usuario implicado en accidente como posible responsable (b)."}},
{n:17,q:"Los agentes de la autoridad, encargados de la vigilancia del tráfico, podrán someter a las pruebas de detección del grado de intoxicación alcohólica a:",o:{a:"Los conductores de vehículos y demás usuarios de la vía implicados directamente como posibles responsables de un accidente de circulación.",b:"Los conductores de vehículos y demás usuarios de la vía que sean denunciados por la comisión de alguna infracción conforme a lo tipificado en la Ley de Seguridad Vial.",c:"Los que con ocasión de conducir un vehículo sean requeridos al efecto por la autoridad o sus agentes, dentro de los programas de controles preventivos ordenados por dicha autoridad.",d:"Cualquiera de los descritos en las respuestas anteriores."},correct:"d",why:{d:"Los agentes pueden someter a pruebas de alcoholemia a cualquiera de los tres grupos descritos: posibles responsables de accidente (a), denunciados por infracción (b) y requeridos en controles preventivos (c)."}},
{n:18,q:"Indique cuál de los siguientes no está obligado a someterse a las pruebas de determinación del grado de impregnación alcohólica:",o:{a:"El ocupante de un vehículo que, al descender del mismo, es atropellado por una motocicleta.",b:"Un jinete que conduce su caballo con signos evidentes de haber consumido bebidas alcohólicas.",c:"Un pastor que atraviesa su rebaño por una calle transitada obligando a los vehículos a frenar.",d:"Ninguno de los anteriores."},correct:"b",why:{b:"El jinete que conduce su caballo no está obligado a someterse a las pruebas de alcoholemia porque el caballo no es un vehículo de motor y el jinete no es usuario de la vía en el sentido de la LSV a estos efectos."}},
{n:19,q:"Indique cuál de los siguientes está obligado a someterse a las pruebas de determinación del grado de impregnación alcohólica:",o:{a:"Un peatón que cruza con el semáforo en rojo.",b:"El conductor de una carreta tirada por caballos que es parado dentro de un control preventivo de alcoholemia.",c:"El conductor de un patinete eléctrico que circula por dirección prohibida",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Los tres están obligados: el peatón infractor (a), el conductor de carreta en control preventivo (b) y el conductor de patinete que comete una infracción (c)."}},
{n:20,q:"Comete delito contra la seguridad vial:",o:{a:"El conductor de una bicicleta que arroja una tasa de alcoholemia de 0,75 mg de alcohol por litro de aire espirado.",b:"El peatón que, bajo la influencia de bebidas alcohólicas, irrumpe en la calzada provocando un accidente de tráfico con resultado de daños materiales.",c:"Un jinete que no respeta la señal de ceda el paso y que, posteriormente, se niega a someterse a las pruebas de determinación de su grado de impregnación alcohólica.",d:"Ninguno de los anteriores comete delito contra la seguridad vial."},correct:"d",why:{d:"Ninguno comete delito contra la seguridad vial: los delitos del art.379 CP requieren ser conductor de vehículo a motor o ciclomotor; bicicletas, peatones y jinetes quedan excluidos del tipo penal."}},
{n:21,q:"Las tasas de alcoholemia en la conducción, o concentraciones máximas permitidas de alcohol en sangre o en aire espirado, se encuentran establecidas:",o:{a:"En el artículo 14 del Reglamento General de Circulación.",b:"En el artículo 20 del Reglamento General de Circulación.",c:"En el artículo 14 de la Ley de Seguridad Vial.",d:"En el artículo 20 de la Ley de Seguridad Vial."},correct:"b",why:{b:"Las concentraciones máximas de alcohol permitidas para conducir se encuentran establecidas en el artículo 20 del Reglamento General de Circulación (RD 1428/2003)."}},
{n:22,q:"De conformidad con lo establecido en el art.20 del Reglamento General de Circulación, la tasa máxima de alcohol para conductores de vehículos o bicicletas es:",o:{a:"En sangre 0,5 gramos por litro y en aire espirado 0,25 miligramos por litro.",b:"En sangre 0,3 gramos por litro y en aire espirado 0,15 miligramos por litro.",c:"En sangre 15 gramos por litro y en aire espirado 0,5 miligramos por litro.",d:"Las tasas de alcoholemia no se regulan en dicho Reglamento, sino en la Ley de Seguridad Vial."},correct:"a",why:{a:"La tasa máxima general para conductores de vehículos o bicicletas es de 0,5 g/l en sangre y 0,25 mg/l en aire espirado, conforme al art.20 del RGC."}},
{n:23,q:"De conformidad con lo establecido en el art.20 del Reglamento General de Circulación, no podrán conducir con una tasa de alcohol en sangre superior a 0,3 gramos por litro, o de alcohol en aire espirado superior a 0,15 miligramos/litro:",o:{a:"Los conductores de vehículos destinados al transporte de mercancías con MMA superior a 3.500 Kg.",b:"Los conductores de vehículos destinados al transporte de viajeros de más de nueve plazas o de vehículos de servicio público.",c:"Los conductores de vehículos de transporte escolar o de menores, de mercancías peligrosas, de servicio de urgencia o de transportes especiales.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El límite reducido de 0,3 g/l en sangre o 0,15 mg/l en aire espirado aplica a los tres grupos: transporte de mercancías pesadas (a), viajeros/servicio público (b) y transporte escolar/peligroso/urgencia (c)."}},
{n:24,q:"De conformidad con lo establecido en el art.20 del Reglamento General de Circulación, la tasa máxima de alcohol para conductores en general es:",o:{a:"0'8 mg de alcohol por litro de aire espirado.",b:"0'25 mg de alcohol por litro de aire espirado.",c:"0'25 gramos de alcohol por litro de aire espirado.",d:"0'4 gramos de alcohol por litro de sangre."},correct:"b",why:{b:"La tasa máxima general de alcohol en aire espirado para conductores es de 0,25 mg/l (miligramos por litro), conforme al art.20 del RGC."}},
{n:25,q:"No se pueden conducir vehículos destinados al transporte de mercancías con MMA superior a 3.500 Kg, con una tasa superior a:",o:{a:"0'5 gramos de alcohol por litro de aire espirado.",b:"0'5 mg, de alcohol por litro de sangre.",c:"0'15 mg, de alcohol por litro de aire espirado.",d:"0'3 gramos de alcohol por litro de aire espirado."},correct:"c",why:{c:"Los vehículos de transporte de mercancías con MMA superior a 3.500 kg tienen una tasa máxima de 0,15 mg/l en aire espirado (o 0,3 g/l en sangre)."}},
{n:26,q:"No se pueden conducir vehículos destinados al transporte de viajeros de más de nueve plazas, con una tasa superior a:",o:{a:"0'3 gramos de alcohol por litro de sangre.",b:"0'3 mg, de alcohol por litro de sangre.",c:"0'15 gramos de alcohol por litro de aire espirado.",d:"0'15 mg, de alcohol por litro de sangre."},correct:"a",why:{a:"Los vehículos de transporte de viajeros de más de 9 plazas tienen un límite de 0,3 gramos por litro de sangre (equivalente a 0,15 mg/l en aire espirado)."}},
{n:27,q:"No se pueden conducir vehículos destinados al servicio público con una tasa superior a:",o:{a:"0'4 mg. de alcohol por litro de sangre.",b:"0'4 gramos de alcohol por litro de sangre.",c:"0'15 mg, de alcohol por litro de aire espirado.",d:"0'15 mg, de alcohol por litro de sangre."},correct:"c",why:{c:"Los vehículos de servicio público tienen un límite de 0,15 mg/l en aire espirado (equivalente a 0,3 g/l en sangre), conforme al art.20 del RGC."}},
{n:28,q:"No se pueden conducir vehículos destinados al transporte escolar y de menores con una tasa superior a:",o:{a:"0'4 mg. de alcohol por litro de sangre.",b:"0'4 gramos de alcohol por litro de sangre.",c:"0'15 mg, de alcohol por litro de aire espirado.",d:"0'15 mg, de alcohol por litro de sangre."},correct:"c",why:{c:"Los vehículos de transporte escolar y de menores tienen un límite de 0,15 mg/l en aire espirado (0,3 g/l en sangre), igual que los de servicio público y mercancías pesadas."}},
{n:29,q:"No se pueden conducir vehículos que transporten mercancías peligrosas con una tasa superior a:",o:{a:"0'15 mg, de alcohol por litro de aire espirado.",b:"0'3 gramos de alcohol por litro de sangre.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas expresan el mismo límite: 0,15 mg/l en aire espirado (a) equivale a 0,3 g/l en sangre (b); ambas son correctas para vehículos de mercancías peligrosas."}},
{n:30,q:"No se pueden conducir vehículos de servicio de urgencia con una tasa superior a:",o:{a:"0'15 gramos de alcohol por litro de sangre.",b:"0'3 mg, de alcohol por litro de aire espirado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{d:"Las dos opciones son incorrectas: la tasa para vehículos de urgencia es 0,15 mg/l en aire espirado (no 0,3 mg/l) y 0,3 g/l en sangre (no 0,15 g/l)."}},
{n:31,q:"El art.20 del Reglamento General de Circulación establece que los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos/litro, ni de alcohol en aire espirado de 0,15 milígramos/litro:",o:{a:"Durante los dos años siguientes a la obtención del permiso o licencia de conducción.",b:"Durante los tres años siguientes a la obtención del permiso o licencia de conducción.",c:"Durante el año siguiente a la obtención del permiso o licencia de conducción",d:"Durante los 18 meses siguientes a la obtención del permiso o licencia de conducción."},correct:"a",why:{a:"El límite reducido de 0,3 g/l en sangre y 0,15 mg/l en aire espirado se aplica a los conductores noveles durante los dos años siguientes a la obtención del permiso o licencia."}},
{n:32,q:"De conformidad con lo establecido en el artículo 22 del Reglamento General de Circulación, respecto a las pruebas para detectar la posible intoxicación por alcohol, indique la afirmación incorrecta:",o:{a:"Se practicarán por los agentes encargados de la vigilancia del tráfico.",b:"A efectos de contraste y exclusivamente a petición del interesado, se podrán repetir las pruebas, que podrán consistir en análisis de sangre, orina u otros análogos.",c:"Consistirán normalmente en la verificación del aire espirado mediante etilómetros oficialmente autorizados.",d:"Determinarán de forma cuantitativa el grado de impregnación alcohólica de los interesados."},correct:"b",why:{b:"La opción b) es incorrecta: las pruebas de contraste no consisten en análisis de sangre, orina u otros análogos sino en una segunda verificación por aire espirado mediante etilómetro."}},
{n:33,q:"De conformidad con lo establecido en el artículo 22 del Reglamento General de Circulación, cuando las personas obligadas a someterse a las pruebas de alcoholemia sufrieran lesiones, dolencias o enfermedades cuya gravedad impida la práctica de las mismas:",o:{a:"Los agentes encargados de realizarlas decidirán las que puedan ser practicadas, trasladando al interesado al centro médico más próximo.",b:"El personal facultativo del centro médico al que fuesen evacuados decidirá las que se hayan de realizar.",c:"El personal facultativo solicitara autorización del interesado para que este preste su consentimiento para la realización de las referidas pruebas.",d:"Todas las respuestas anteriores son incorrectas."},correct:"b",why:{b:"Cuando lesiones o dolencias impiden la práctica de las pruebas, es el personal facultativo del centro médico al que sea evacuado el interesado quien decide las pruebas que se han de realizar."}},
{n:34,q:"Si el resultado de la prueba de alcoholemia practicada diere un grado de impregnación superior a 0'5 gramos de alcohol por litro de sangre, el agente de la autoridad:",o:{a:"Formulará la correspondiente denuncia.",b:"Redactará el correspondiente atestado.",c:"Someterá al afectado a una segunda prueba a efectos de contraste, mediante análisis de sangre, orina u otros análogos.",d:"Para una mayor garantía y a efectos de contraste someterá al interesado a una segunda prueba de detección alcohólica por aire espirado, mediante un procedimiento similar al que sirvió para efectuar la primera prueba, informándole de ello previamente."},correct:"d",why:{d:"Si el resultado supera 0,5 g/l en sangre, el agente someterá al interesado a una segunda prueba de detección por aire espirado similar a la primera, informándole previamente de ello."}},
{n:35,q:"El agente que practica la prueba de alcoholemia deberá:",o:{a:"Informar al interesado que tiene derecho a controlar por sí o por cualquiera de sus acompañantes o testigos presentes que entre la realización de la primera y la segunda prueba transcurre un tiempo mínimo de diez minutos.",b:"Informar al interesado que tiene derecho a formular cuantas alegaciones u observaciones tenga por conveniente, que deberá aportar mediante un representante oficial, las cuales se consignarán por diligencia en el plazo máximo de 5 días.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El agente debe informar del derecho a controlar que entre la primera y la segunda prueba transcurre un mínimo de diez minutos. La opción b) es incorrecta porque las alegaciones pueden aportarse por cualquier medio, no solo mediante representante oficial."}},
{n:36,q:"El agente que practica la prueba de alcoholemia deberá:",o:{a:"Advertir a la persona sometida que tiene derecho a contrastar los resultados obtenidos mediante análisis de sangre, orina u otros análogos que el personal facultativo del centro médico al que sea trasladado estime más adecuado.",b:"Informar a la persona sometida del derecho que tiene a formular cuantas alegaciones y observaciones tenga por conveniente, por sí o por medio de acompañante o defensor, si lo tuviere, las cuales se consignarán por diligencia.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El agente debe cumplir ambas obligaciones: advertir del derecho a contrastar resultados por análisis médicos (a) e informar del derecho a formular alegaciones directamente o por medio de defensor (b)."}},
{n:37,q:"Según el artículo 14.5 de la ley de Seguridad Vial (RDL 6/2015)...",o:{a:"El procedimiento, las condiciones y los términos en que se realizarán las pruebas para la detección de alcohol o drogas se determinarán reglamentariamente.",b:"A efectos de contraste, a petición del interesado, se podrán repetir las pruebas para la detección de alcohol o drogas, que consistirán preferentemente en análisis de sangre, salvo causas excepcionales debidamente justificadas.",c:"Las pruebas para la detección de alcohol consistirán en la verificación del aire espirado, mediante dispositivos autorizados.",d:"Las pruebas para la detección de la presencia de drogas consistirán en una prueba salival mediante un dispositivo autorizado y en un posterior análisis de una muestra salival en cantidad suficiente."},correct:"b",why:{b:"El art.14.5 LSV establece que las pruebas de contraste, a petición del interesado, consistirán preferentemente en análisis de sangre, salvo causas excepcionales justificadas."}},
{n:38,q:"Respecto a las pruebas de alcoholemia, indique la afirmación incorrecta:",o:{a:"En caso de que el sometido a la prueba de determinación del grado de impregnación alcohólica decida la realización de análisis de contraste, el agente de la autoridad adoptará las medidas más adecuadas para su traslado al centro sanitario más próximo.",b:"El importe de los análisis deberá ser previamente depositado por el interesado y con él se atenderá el pago, cuando el resultado de la prueba de contraste sea positivo, devolviéndose el importe si fuere negativo.",c:"El importe de los análisis de contraste del grado de impregnación alcohólica correrán a cargo de los órganos periféricos de la Jefatura Central de Tráfico, o de las autoridades municipales competentes, cuando sea negativo.",d:"Se advertirá a la persona sometida a examen del derecho que tiene a controlar por si, o por medio de abogado si lo tuviere, que entre la realización de la primera y de la segunda prueba medie un tiempo mínimo de 10 minutos."},correct:"d",why:{d:"La opción d) es incorrecta: el derecho a controlar que medie un mínimo de 10 minutos puede ejercerlo el interesado por sí mismo o mediante acompañante o testigo, no necesariamente mediante abogado."}},
{n:39,q:"En lo que respecta a las pruebas de alcoholemia, a efectos de contraste pueden repetirse las pruebas de determinación del grado de impregnación alcohólica, mediante análisis de sangre, orina u otros análogos:",o:{a:"Cuando así lo determine el agente encargado de practicarlas.",b:"Cuando lo solicite el interesado.",c:"Cuando el conductor se halle implicado en un accidente de circulación con víctimas mortales.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"Las pruebas de contraste (análisis de sangre, orina u otros) solo pueden repetirse a petición del interesado, no por decisión del agente ni por el mero hecho de estar implicado en un accidente."}},
{n:40,q:"En lo que respecta a las pruebas de alcoholemia, a efectos de contraste pueden repetirse las pruebas de determinación del grado de impregnación alcohólica, mediante análisis de sangre, orina u otros análogos:",o:{a:"Por orden de la autoridad judicial.",b:"Cuando así lo determine el agente encargado de practicarlas.",c:"Cuando el conductor se halle implicado directamente como posible responsable en un accidente de circulación.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"Las pruebas de contraste mediante análisis de sangre u otros también pueden repetirse por orden de la autoridad judicial."}},
{n:41,q:"Según el artículo 23.4 del RD. 1428/2003, en el caso de que el sometido a una prueba de alcoholemia por aire espirado decida contrastar los resultados obtenidos mediante análisis de sangre, el importe de dichos análisis:",o:{a:"Será satisfecho por el interesado en el momento de la prueba.",b:"Será satisfecho por el interesado con posterioridad a la prueba, solo en el supuesto de que el resultado de dicho análisis fuese positivo.",c:"Será satisfecho por la Administración en el momento de la prueba, repercutiéndolo al interesado cuando dicho resultado sea positivo.",d:"Deberá ser depositado previamente por el interesado y con él se atenderá el pago cuando el resultado de la prueba de contraste sea positivo, devolviéndose el importe al interesado si fuere negativo."},correct:"d",why:{d:"El interesado debe depositar previamente el importe; si el resultado de contraste es positivo se aplica al pago y si es negativo se le devuelve."}},
{n:42,q:"Cuando el resultado de la segunda prueba de alcoholemia o el de los análisis efectuados fuera positivo, además de ajustarse a lo dispuesto en la LECRIM, el agente de la autoridad deberá:",o:{a:"Describir en el boletín de denuncia los signos y reacciones externas que aprecie en el sometido.",b:"Consignar en el boletín o atestado las advertencias hechas al interesado, especialmente las referidas al derecho que le asiste a elegir centro médico sanitario para el análisis de sangre u orina.",c:"Conducir al sometido, o al que se negare a la prueba, en el caso de que los hechos revistan caracteres delictivos, al juzgado correspondiente a los efectos que procedan.",d:"Describir en el atestado o boletín de denuncia el procedimiento seguido para realizar la prueba y la conducta y comportamiento del conductor durante el desarrollo de la misma."},correct:"c",why:{c:"Si el resultado positivo reviste caracteres delictivos, el agente debe conducir al sometido (o quien se negó a la prueba) al juzgado correspondiente."}},
{n:43,q:"Cuando el resultado de la segunda prueba de alcoholemia o el de los análisis efectuados fuera positivo, además de ajustarse a lo dispuesto en la LECRIM, el agente de la autoridad deberá:",o:{a:"Describir con precisión en el boletín de denuncia o atestado las diligencias que practique y el procedimiento seguido para efectuar la prueba o pruebas de detección, haciendo constar los datos necesarios para la identificación del instrumento empleado, cuyas características genéricas también detallará.",b:"Describir en el boletín de denuncia los signos y reacciones externas que aprecie en el sometido.",c:"Consignar en el boletín o atestado las advertencias hechas al interesado, especialmente la referidas al derecho que le asiste a elegir centro médico sanitario para el análisis de sangre u orina.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"El agente debe describir con precisión las diligencias practicadas, el procedimiento de detección y los datos identificativos del instrumento empleado, incluyendo sus características genéricas."}},
{n:44,q:"Cuando el resultado de la segunda prueba de alcoholemia o el de los análisis efectuados fuera positivo, además de ajustarse a lo dispuesto en la LECrim., el agente de la autoridad deberá:",o:{a:"Consignar las advertencias hechas al interesado, especialmente la del derecho que le asiste a contrastar los resultados obtenidos mediante análisis adecuados, acreditándose en las diligencias las pruebas o análisis practicados en el Centro Sanitario al que fue trasladado el interesado.",b:"Detener al conductor para su inmediata puesta a disposición de la autoridad judicial y proceder a la inmovilización del vehículo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El agente debe consignar las advertencias hechas, especialmente el derecho del interesado a contrastar resultados, acreditando en las diligencias los análisis practicados en el centro sanitario."}},
{n:45,q:"De conformidad con lo establecido en el artículo 25 del Reglamento General de Circulación, puede procederse a la inmovilización del vehículo:",o:{a:"Cuando el resultado de las pruebas de alcoholemia, y de los análisis en su caso, fuere positivo, a no ser que pueda hacerse cargo de la conducción otra persona debidamente habilitada.",b:"En los casos de negativa a efectuar las pruebas de detección alcohólica.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Procede la inmovilización tanto cuando el resultado de alcoholemia es positivo sin conductor alternativo habilitado (a) como cuando hay negativa a realizar las pruebas (b)."}},
{n:46,q:"La inmovilización de un vehículo, como consecuencia de la obtención de una tasa positiva de alcoholemia en la persona que lo conduce, será dejada sin efecto:",o:{a:"Tan pronto como desaparezca la causa que la motivó, siempre y cuando la autoridad judicial no hubiese determinado otra cosa.",b:"Tan pronto como pueda sustituir al conductor otro habilitado para ello que ofrezca garantía suficiente a los agentes de la autoridad y cuya actuación haya sido requerida por el interesado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"La inmovilización cesa en dos supuestos: cuando desaparece la causa salvo orden judicial en contrario (a) y cuando un conductor habilitado puede sustituir al infractor a petición del interesado (b)."}},
{n:47,q:"Las infracciones al Reglamento General de Circulación por superar la tasa de alcoholemia tienen la consideración de:",o:{a:"Leves.",b:"Graves.",c:"Muy graves.",d:"Menos graves."},correct:"c",why:{c:"Superar la tasa de alcoholemia permitida constituye una infracción muy grave conforme al Reglamento General de Circulación."}},
{n:48,q:"De acuerdo con la doctrina del Tribunal Constitucional, la prueba de alcoholemia:",o:{a:"No vulnera el derecho a la integridad física cuando se realiza mediante el procedimiento de aire espirado.",b:"Vulnera el derecho a la integridad física cuando se obliga al sujeto a la extracción de sangre.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El TC establece que soplar no vulnera la integridad física (a), pero la extracción forzosa de sangre sí podría vulnerarla (b); ambas afirmaciones son correctas."}},
{n:49,q:"De acuerdo con la doctrina del Tribunal Constitucional, la prueba de alcoholemia:",o:{a:"No vulnera el derecho a no declarar contra sí mismo.",b:"No vulnera el derecho a no declararse culpable.",c:"Constituye una modalidad especial de pericia de resultado incierto.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El TC ha declarado que la prueba de alcoholemia no vulnera el derecho a no declarar contra sí mismo (a) ni el de no declararse culpable (b), y que constituye una pericia especial (c); los tres son correctos."}},
{n:50,q:"De acuerdo con la doctrina del Tribunal Constitucional, la prueba de alcoholemia:",o:{a:"No vulnera el derecho constitucional a la libertad.",b:"No es la única, ni es imprescindible para acreditar un delito de conducción influenciada.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El TC afirma que la prueba de alcoholemia no vulnera el derecho a la libertad (a) y que no es prueba única ni imprescindible para acreditar la conducción influenciada (b); ambas son correctas."}},
{n:51,q:"Respecto a la prueba de alcoholemia y de acuerdo con la doctrina del Tribunal Constitucional, indique la respuesta incorrecta:",o:{a:"La mera parada de un conductor con la finalidad de someterle a la prueba de alcoholemia no constituye detención ya que queda enmarcada dentro del conjunto de posibilidades policiales de prevención.",b:"Para que exista delito de conducción influenciada por el alcohol basta con probar su influencia en las facultades para conducir un vehículo a motor.",c:"Para destruir la presunción de inocencia, es preciso que los agentes que han realizado la prueba la ratifiquen en juicio oral.",d:"Carece de valor probatorio el test de alcoholemia en el que no se informa del derecho a una segunda prueba y al análisis de contraste"},correct:"b",why:{b:"La opción b) es incorrecta: para el TC no basta con probar la influencia del alcohol en las facultades de conducir; también es necesario acreditar la ingesta y la relación causal con la conducción."}},
{n:52,q:"De acuerdo con la doctrina del Tribunal Constitucional, para que exista delito de conducción influenciada debe quedar probado/a:",o:{a:"La ingesta de alcohol.",b:"La influencia del alcohol en las facultades para conducir un vehículo a motor.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Para el TC deben quedar probadas tanto la ingesta de alcohol (a) como su influencia en las facultades para conducir (b); ambas son necesarias."}},
{n:53,q:"De acuerdo con la doctrina del Tribunal Constitucional, durante la práctica de la prueba de alcoholemia:",o:{a:"No es necesaria la presencia de letrado.",b:"Será preceptiva la presencia de letrado.",c:"Será preceptiva la presencia de letrado cuando se realice la extracción de sangre, porque constituye una injerencia prohibida por el art.15 de la Constitución Española.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"El TC establece que durante la práctica de la prueba de alcoholemia no es necesaria la presencia de letrado, ya que no se trata de una declaración sino de una pericia."}},
{n:54,q:"Respecto a las pruebas de alcoholemia, en el ámbito de la justicia ordinaria, los tribunales han sentenciado:",o:{a:"Que para que exista delito el resultado positivo debe serlo en las dos pruebas de alcoholemia.",b:"Que cuando la tasa de alcohol supere los 0,60 mg/l de aire espirado, no se precisa acreditar la influencia del alcohol en la conducción, para entender cometido este delito.",c:"Que la no realización de una segunda prueba no supone la conculcación de ningún derecho fundamental, si se ha ofrecido análisis de sangre a efectos de contraste.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Los tribunales han sentenciado los tres criterios: resultado positivo en ambas pruebas (a), umbral de 0,60 mg/l sin necesidad de acreditar influencia (b) y que no hay vulneración si se ofreció contraste por sangre (c)."}},
{n:55,q:"Respecto a las pruebas de alcoholemia, en el ámbito de la justicia ordinaria, los tribunales han sentenciado que:",o:{a:"Aún con sintomatología etílica, la conducción con tasas inferiores a las permitidas es atípica.",b:"Los resultados de los etilómetros no sometidos a control metrológico del Estado no pueden constituir prueba de cargo.",c:"La caducidad del certificado de verificación del etilómetro impide valorar la prueba de alcoholemia.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Los tribunales han sentenciado los tres criterios: conducción atípica con tasas inferiores (a), etilómetros sin control metrológico no son prueba de cargo (b) y certificado caducado impide valorar la prueba (c)."}},
{n:56,q:"Las pruebas de alcoholemia por aire espirado deben realizarse con etilómetros que cumplan las normas metrológicas exigidas por el Estado. El control metrológico de estos instrumentos se regula actualmente en...",o:{a:"Anexo X de la Orden ICT/155/2020.",b:"Anexo XI de la Orden ICT/155/2020.",c:"Anexo XII de la Orden ICT/155/2020.",d:"Anexo XIII de la Orden ICT/155/2020."},correct:"b",why:{b:"El control metrológico de los etilómetros está regulado en el Anexo XI de la Orden ICT/155/2020."}},
{n:57,q:"El control metrológico de los etilómetros está referido a:",o:{a:"Aprobación de modelo, verificación primitiva, verificación periódica y verificación después de reparación.",b:"Aprobación del instrumento, verificación del modelo, verificación periódica y verificación tras reparación.",c:"Aprobación del aparato, verificación del modelo y verificación periódica, antes y después de una reparación.",d:"Aprobación del instrumento, verificación constante y revisión periódica."},correct:"a",why:{a:"El control metrológico de los etilómetros comprende: aprobación de modelo, verificación primitiva, verificación periódica y verificación después de reparación."}},
{n:58,q:"La verificación periódica de los etilómetros se lleva a cabo:",o:{a:"Una vez al año por cuenta del usuario.",b:"Una vez al año por cuenta del fabricante.",c:"Dos veces al año por cuenta del usuario.",d:"Dos veces al año por cuenta del fabricante."},correct:"a",why:{a:"La verificación periódica de los etilómetros se realiza una vez al año y corre por cuenta del usuario del instrumento."}},
{n:59,q:"La verificación después de reparación de los etilómetros se realiza:",o:{a:"Cada vez que el equipo se avería.",b:"Cada vez que el equipo se desprecinta para recalibrarlo o repararlo.",c:"Una vez al año para recalibrarlo, aunque no haya sufrido ninguna avería.",d:"Dos veces al año para recalibrarlo, aunque no haya sufrido ninguna avería."},correct:"b",why:{b:"La verificación después de reparación se realiza cada vez que el equipo se desprecinta para recalibrarlo o repararlo, independientemente de si ha sufrido avería."}},
{n:60,q:"La Orden ICT/155/2020, es aplicable a los etilómetros puestos en funcionamiento a partir de...",o:{a:"14/10/2021.",b:"14/10/2020.",c:"24/10/2021.",d:"24/10/2020."},correct:"a",why:{a:"La Orden ICT/155/2020 es aplicable a los etilómetros puestos en funcionamiento a partir del 14/10/2021."}},
{n:61,q:"A los etilómetros puestos en funcionamiento en el periodo comprendido entre el 08/12/2006 y 23/10/2020, les resulta de aplicación...",o:{a:"La Orden ICT 3707/2006.",b:"La Orden ITC 3707/2006.",c:"La Orden ICT 7307/2006.",d:"La Orden ITC 7307/2006."},correct:"b",why:{b:"A los etilómetros puestos en funcionamiento entre el 08/12/2006 y el 23/10/2020 les resulta de aplicación la Orden ITC 3707/2006."}},
{n:62,q:"De conformidad con lo dispuesto en la Orden ICT/155/2020 el error máximo permitido (emp) en concentraciones de alcohol en aire espirado iguales o inferiores a 0,400 mg/l,...",o:{a:"Es del 7,5%",b:"Es de 0,03 mg/l.",c:"Se calcula empleando la fórmula 0,75 x C-1,35.",d:"Ninguna de las respuestas anteriores correcta."},correct:"b",why:{b:"Para concentraciones de alcohol en aire espirado iguales o inferiores a 0,400 mg/l, el error máximo permitido es de 0,03 mg/l."}},
{n:63,q:"De conformidad con lo dispuesto en la Orden ICT/155/2020 el error máximo permitido (emp) en concentraciones de alcohol en aire espirado superiores a 0,400 mg/l, e iguales o inferiores a 1 mg/l...",o:{a:"Es del 7,5%",b:"Es de 0,03 mg/l.",c:"Se calcula empleando la fórmula 0,75 x C-1,35.",d:"Ninguna de las respuestas anteriores correcta."},correct:"a",why:{a:"Para concentraciones superiores a 0,400 mg/l e iguales o inferiores a 1 mg/l, el error máximo permitido es del 7,5%."}},
{n:64,q:"De conformidad con lo dispuesto en la Orden ICT/155/2020 el error máximo permitido (emp) en concentraciones de alcohol en aire espirado superiores a 2 mg/l, e iguales o inferiores a 2,455 mg/l...",o:{a:"Es del 7,5%",b:"Es de 0,03 mg/l.",c:"Se calcula empleando la fórmula 0,75 x C-1,35.",d:"Ninguna de las respuestas anteriores correcta."},correct:"c",why:{c:"Para concentraciones superiores a 2 mg/l e iguales o inferiores a 2,455 mg/l, el error máximo permitido se calcula mediante la fórmula 0,75 x C - 1,35."}},
{n:65,q:"De conformidad con lo dispuesto en la Orden ICT/155/2020 el error máximo permitido (emp) en concentraciones de alcohol en aire espirado superiores a 2,455 mg/l,...",o:{a:"Es del 7,5%",b:"Es de 0,03 mg/l.",c:"Se calcula empleando la fórmula 0,75 x C-1,35.",d:"Ninguna de las respuestas anteriores correcta."},correct:"c",why:{c:"Para concentraciones superiores a 2,455 mg/l, el error máximo permitido también se calcula mediante la fórmula 0,75 x C - 1,35."}},
{n:66,q:"El procedimiento de colaboración entre los profesionales de las FFCCSS y el personal de los Centros Sanitarios dependientes de la Consellería de Sanidad de la Generalitat Valenciana, al objeto de realizar las pruebas de contraste en alcohol y drogas en sangre, se rige por...",o:{a:"El Protocolo de colaboración para la realización de pruebas de contraste elaborado por Les Corts Valencianes y la Federación Valenciana de Municipios y Provincias.",b:"El Protocolo de actuación y coordinación para la realización de pruebas en alcohol y drogas de la Consellería de Salud Universal y Salud Pública de la Generalitat Valenciana.",c:"El Protocolo de colaboración entre el personal sanitario de la Generalitat Valenciana y los miembros de las FFCCSS, para extracciones de sangres, con objeto de contrastar alcohol y/o drogas en conductores de vehículos a motor.",d:"El Protocolo de actuación y coordinación para la realización de pruebas de contraste en alcohol y drogas en sangre de la Consellería de Sanidad Universal y Salud Pública de la Generalitat Valenciana."},correct:"d",why:{d:"El procedimiento de colaboración se rige por el Protocolo de actuación y coordinación para la realización de pruebas de contraste en alcohol y drogas en sangre de la Consellería de Sanidad Universal y Salud Pública de la Generalitat Valenciana."}},
{n:67,q:"De conformidad con lo establecido en el art.77 de la Ley de Seguridad Vial, constituye infracción muy grave:",o:{a:"Conducir con tasas de alcohol superiores a las que reglamentariamente se establezcan, o con presencia en el organismo de drogas.",b:"Conducir con una tasa de alcohol en aire espirado superior a 0,60 mg/l.",c:"Conducir con una tasa de alcohol en sangre superior a 1,2 g/l.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"El art.77 LSV tipifica como infracción muy grave conducir con tasas de alcohol superiores a las reglamentariamente establecidas o con presencia de drogas en el organismo."}},
{n:68,q:"Conforme a lo previsto en el art.77 de la Ley de Seguridad Vial, incumplir la obligación de todos los conductores de vehículos, y de los demás usuarios de la vía cuando se hallen implicados en algún accidente de tráfico o hayan cometido una infracción, de someterse a las pruebas que se establezcan para la detección de alcohol o de la presencia de drogas en el organismo, constituye infracción:",o:{a:"Muy grave.",b:"Grave.",c:"Leve.",d:"La Ley de Seguridad Vial no se pronuncia sobre este extremo."},correct:"a",why:{a:"Negarse a someterse a las pruebas de detección de alcohol o drogas constituye infracción muy grave conforme al art.77 de la Ley de Seguridad Vial."}},
{n:69,q:"Cuando, además del riesgo que conlleva la circulación de un vehículo a motor bajo la influencia de bebidas alcohólicas, se produjere un resultado lesivo, cualquiera que sea su gravedad, los jueces y tribunales:",o:{a:"Apreciarán solo la infracción más gravemente penada.",b:"Sancionarán conjuntamente ambas infracciones.",c:"Sancionarán la infracción más gravemente penada en su grado máximo.",d:"Sancionarán ambas infracciones en su grado mínimo."},correct:"a",why:{a:"Cuando a la conducción bajo influencia se añade un resultado lesivo, los jueces apreciarán solo la infracción más gravemente penada, aplicando el concurso ideal de delitos."}},
{n:70,q:"Cuando, además del riesgo que conlleva la circulación de un vehículo a motor bajo la influencia de bebidas alcohólica, se produjere un resultado lesivo, cualquiera que sea su gravedad, los jueces y tribunales:",o:{a:"Apreciarán tan solo la infracción más gravemente penada, en su mitad superior.",b:"Condenarán en todo caso al resarcimiento de la responsabilidad civil que se haya originado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas son correctas: se aplica la pena más grave en su mitad superior (a) y se condena al resarcimiento de la responsabilidad civil originada (b)."}},
{n:71,q:"De acuerdo con la doctrina del Tribunal Constitucional, para apreciar el ilícito penal, en el caso de que exista conducción influenciada, ni siquiera se exige necesariamente la realización de la prueba de alcoholemia ya que el Juzgador puede llegar al convencimiento sobre dicha influencia a partir de los testimonios:",o:{a:"Del propio acusado.",b:"De los policías intervinientes.",c:"De testigos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El TC admite que la convicción sobre la conducción influenciada puede alcanzarse mediante los testimonios del propio acusado (a), los policías intervinientes (b) o testigos (c); los tres son válidos."}},
{n:72,q:"En los delitos de conducción de vehículos a motor bajo la influencia de bebidas alcohólicas, a la hora de aplicar las penas, los jueces y tribunales:",o:{a:"Procederán según su prudente arbitrio, pudiendo no imponer sanción alguna cuando el procesado acceda a la realización de 90 horas de trabajos en beneficio de la Comunidad.",b:"Procederán según su prudente arbitrio, sin sujetarse a las reglas prescritas en el art.66 del Código Penal.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Los jueces y tribunales proceden según su prudente arbitrio sin sujetarse a las reglas prescritas en el art.66 CP, conforme a la regulación específica de los delitos contra la seguridad vial."}},
{n:73,q:"Con respecto a las pruebas de alcoholemia, señale la afirmación incorrecta:",o:{a:"En caso de accidente de tráfico, los peatones que resulten implicados están obligados a someterse a las pruebas de detección alcohólica.",b:"Si un peatón, implicado en un accidente de tráfico se somete a las pruebas de detección alcohólica y arroja un resultado positivo puede ser sancionado administrativamente.",c:"Un peatón implicado en un accidente de tráfico que arroja un resultado positivo en las pruebas de alcoholemia jamás incurre en delito contra la seguridad vial, por muy alta su tasa de alcoholemia.",d:"Un peatón implicado en un accidente de tráfico puede ser sancionado administrativamente si se niega a realizar la prueba de alcoholemia."},correct:"b",why:{b:"La opción b) es incorrecta: un peatón que arroja resultado positivo en alcoholemia NO puede ser sancionado administrativamente; las sanciones administrativas de alcoholemia van dirigidas a conductores y usuarios de vehículos, no a peatones."}},
{n:74,q:"Los peatones que resulten implicados en accidentes de circulación:",o:{a:"Están obligados a someterse a las pruebas de alcoholemia.",b:"En el supuesto de que arrojen un resultado positivo en las pruebas de alcoholemia, no pueden ser denunciados administrativamente.",c:"Pueden ser sancionados administrativamente, si se niegan a realizar las pruebas de alcoholemia.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones son correctas: los peatones están obligados a someterse (a), no pueden ser sancionados administrativamente por resultado positivo (b) y sí pueden serlo si se niegan a realizarlas (c)."}},
{n:75,q:"Para que un atestado realizado por un presunto delito de conducción bajo la influencia de bebidas alcohólicas pueda considerarse prueba legítima y se convierta en un auténtico elemento probatorio en el proceso penal:",o:{a:"Debe existir una ratificación de los agentes en el juicio oral.",b:"Debe realizarse ante dos testigos imparciales.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Para que el atestado sea prueba legítima en el proceso penal, los agentes que lo elaboraron deben ratificarlo en el juicio oral."}},
{n:76,q:"El conductor de un carro tirado por caballos:",o:{a:"Está obligado a someterse a las pruebas para la determinación de su grado de impregnación alcohólica, si fuere requerido para ello, dentro un control preventivo.",b:"En el supuesto que se negase a someterse a las pruebas para la determinación de su grado de impregnación alcohólica podría ser considerado autor de un delito contra la seguridad vial.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El conductor de un carro tirado por caballos está obligado a someterse a las pruebas si es requerido en un control preventivo. Sin embargo, negarse no configura delito contra la seguridad vial porque el carro no es vehículo a motor."}},
{n:77,q:"La persona que conduce un rebaño de ovejas por una vía pública:",o:{a:"Está obligada a someterse a las pruebas para la determinación de su grado de impregnación alcohólica, si fuere requerida para ello, dentro de un control preventivo.",b:"Está obligada a someterse a las pruebas para la determinación de su grado de impregnación alcohólica cuando se halle implicada directamente en un accidente como posible responsable del mismo.",c:"Está obligada a someterse a las pruebas para la determinación de su grado de impregnación alcohólica si presenta síntomas evidentes que permitan razonablemente presumir que se halla bajo la influencia de bebidas alcohólicas.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El pastor que conduce un rebaño es usuario de la vía y está obligado a las pruebas en los tres supuestos: control preventivo (a), implicado en accidente (b) y con síntomas evidentes (c)."}},
{n:78,q:"No podrá circular por las vías objeto de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial:",o:{a:"El conductor de cualquier vehículo con presencia de drogas en el organismo.",b:"El conductor que se encuentre bajo los efectos de medicamentos u otras sustancias que alteren su estado físico o mental.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Está prohibido circular tanto con presencia de drogas en el organismo (a) como bajo los efectos de medicamentos u otras sustancias que alteren las capacidades (b); ambas prohibiciones son correctas."}},
{n:79,q:"Con respecto a las pruebas para la detección de la presencia de drogas en el organismo, indique la respuesta incorrecta:",o:{a:"Consistirán en una prueba salival mediante un dispositivo autorizado, y en un posterior análisis de una muestra salival en cantidad suficiente.",b:"A petición del interesado, a efectos de contraste, se podrán repetir las pruebas, que consistirán preferentemente en análisis de sangre, salvo causas excepcionales debidamente justificadas.",c:"Cuando la prueba de contraste arroje un resultado positivo será abonada por la administración correspondiente.",d:"Cuando existan razones justificadas que impidan realizar estas pruebas, se podrá ordenar el reconocimiento médico del sujeto o la realización de los análisis clínicos que los facultativos del centro sanitario al que sea trasladado estimen más adecuados."},correct:"c",why:{c:"La opción c) es incorrecta: cuando la prueba de contraste arroja resultado positivo, el importe debe ser abonado por el interesado, no por la administración."}},
{n:80,q:"Respecto a las pruebas para la detección de la presencia de drogas en el organismo, el personal sanitario vendrá obligado, en todo caso, a dar cuenta del resultado de estas pruebas:",o:{a:"Al Jefe Provincial de Tráfico de la Provincia donde se haya cometido el hecho.",b:"A los órganos competentes para sancionar en las Comunidades Autónomas que tengan transferida esta competencia, cuando proceda.",c:"A las autoridades municipales competentes, cuando proceda.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El personal sanitario debe dar cuenta del resultado a los tres destinatarios: Jefe Provincial de Tráfico (a), órganos autonómicos competentes (b) y autoridades municipales competentes (c)."}},
{n:81,q:"Están obligados a someterse a las pruebas de detección de sustancias estupefacientes, psicotrópicas, estimulantes u otras sustancias análogas:",o:{a:"Las mismas personas que se hallan obligadas a someterse a las pruebas de alcoholemia.",b:"Los conductores de vehículos a motor exclusivamente.",c:"Los conductores de vehículos a motor y de ciclomotores exclusivamente.",d:"Todos los conductores en general. En cuanto al resto de usuarios de la vía, solo en el caso de que se hallen implicados en un accidente de tráfico."},correct:"a",why:{a:"Las mismas personas obligadas a someterse a pruebas de alcoholemia lo están también para las pruebas de detección de sustancias estupefacientes y psicotrópicas."}},
{n:82,q:"La presencia de drogas en el organismo se sanciona administrativamente como infracción de carácter:",o:{a:"Leve.",b:"Grave.",c:"Muy grave.",d:"Menos grave."},correct:"c",why:{c:"La presencia de drogas en el organismo al conducir constituye una infracción administrativa de carácter muy grave, conforme a la Ley de Seguridad Vial."}},
{n:83,q:"Con relación a las pruebas para la detección de drogas tóxicas, estupefacientes y sustancias psicotrópicas en los conductores de vehículos a motor y ciclomotores, el artículo 796 de la Ley de Enjuiciamiento Criminal dispone que la realización de estas pruebas se llevará a cabo:",o:{a:"Por agentes de la policía judicial.",b:"Por agentes de la policía judicial de tráfico.",c:"Por agentes de la policía judicial de tráfico con formación específica.",d:"Preferentemente por agentes de la policía judicial de tráfico con formación específica."},correct:"d",why:{d:"El art.796 LECrim dispone que estas pruebas se realizarán preferentemente por agentes de la policía judicial de tráfico con formación específica."}},
{n:84,q:"El artículo 796 de la Ley de Enjuiciamiento Criminal dispone que cuando el test indiciario salival del conductor arroje un resultado positivo, o el conductor presente signos de haber consumido las referidas sustancias:",o:{a:"Se practicará una segunda prueba, a efectos de contraste, mediante un procedimiento similar al anterior.",b:"El conductor deberá facilitar saliva, en cantidad suficiente, que será analizada en laboratorios homologados, garantizándose la cadena de custodia.",c:"El conductor está obligado a someterse a una extracción de sangre con el fin contrastar los resultados obtenidos mediante el test de saliva.",d:"Se procederá a la inmovilización inmediata del vehículo a no ser que pudiera existir alguna persona, designada por el conductor, que pueda hacerse cargo de la conducción del vehículo."},correct:"b",why:{b:"Ante resultado positivo o signos de consumo, el conductor debe facilitar saliva en cantidad suficiente para ser analizada en laboratorios homologados con garantía de cadena de custodia."}},
{n:85,q:"El artículo 796 de la Ley de Enjuiciamiento Criminal dispone:",o:{a:"Que todo conductor podrá solicitar prueba de contraste consistente en análisis de sangre, salvo causa justificada, en cuyo caso también se podrá solicitar contraste mediante análisis de orina u otras pruebas análogas.",b:"Que cuando se practicaren las pruebas de contraste, se requerirá al personal sanitario que lo realice para que remita el resultado al Juzgado de guardia por el medio más rápido y, en todo caso, antes de 5 días.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El art.796 LECrim recoge ambas previsiones: el derecho del conductor a solicitar contraste por análisis de sangre u orina (a) y la obligación del personal sanitario de remitir el resultado al juzgado antes de 5 días (b)."}},
{n:86,q:"El modelo de acta de signos externos para la determinación de la influencia de drogas en la conducción, se contiene en...",o:{a:"El Anexo II del Oficio de 18 de julio de 2019, del Fiscal Coordinador de Seguridad Vial.",b:"El Anexo I del Oficio de 18 de julio de 2019, del Fiscal Coordinador de Seguridad Vial.",c:"El Anexo II del Oficio de 27/05/2021 del Fiscal de Sala Coordinador de Seguridad Vial.",d:"El Anexo I del Oficio de 27/05/2021 del Fiscal de Sala Coordinador de Seguridad Vial."},correct:"b",why:{b:"El modelo de acta de signos externos para la determinación de la influencia de drogas se contiene en el Anexo I del Oficio de 18 de julio de 2019 del Fiscal Coordinador de Seguridad Vial."}},
{n:87,q:"Los criterios para la elaboración de atestados por delito de conducción bajo la influencia de drogas tóxicas, estupefacientes y sustancias psicotrópicas, se contienen en...",o:{a:"El Oficio de 18 de julio de 2019, del Fiscal Coordinador de Seguridad Vial.",b:"El Oficio de 27/05/2021 del Fiscal de Sala Coordinador de Seguridad Vial.",c:"La Circular 10/2011, de la Fiscalía General del Estado, sobre criterios para la unidad de actuación especializada del Ministerio Fiscal en materia de seguridad vial.",d:"El Dictamen 1/2016 del Fiscal de Sala Coordinador de Seguridad Vial, sobre delitos contra la seguridad vial."},correct:"a",why:{a:"Los criterios para elaborar atestados por conducción bajo influencia de drogas se contienen en el Oficio de 18 de julio de 2019 del Fiscal Coordinador de Seguridad Vial."}}
];